            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "La rue avait tout à fait changé d'aspect depuis le départ de Colin et de Chloé. Maintenant, les feuilles des arbres étaient grandes et les maisons quittaient leur teinte pâle pour se nuancer d'un vert effacé avant d'acquérir le beige doux de l'été. Le pavé devenait élastique et doux sous les pas et l'air sentait la framboise.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "Des fleurs vertes et bleues poussaient le long des trottoirs, et la sève serpentait autour de leurs tiges minces avec un léger bruit humide, comme un baiser d'escargots.", Author = "Boris Vian" },
