            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "J'accuse mes maîtres, dit Wolf, de m'avoir, par leur ton et celui de leurs livres, fait croire à une immobilité possible du monde.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "On ne reste pas parce qu'on aime certaines personnes ; on s'en va parce qu'on en déteste d'autres. Il n'y a que le moche qui vous fasse agir. On est lâche.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "Il y a un paradoxe amusant dans le fait que le gouvernement encourage par tous les moyens les citoyens à boire du cognac et à griller de l'herbe puante, et dans le même temps, arrête et condamne les satyres qui ne font en somme que tenter d'exercer une fonction parfaitement normale mais compliquée à plaisir par les préjugés et autres règlements. Ou plutôt, il n'y a pas de paradoxe ; ce sont les deux aspects d'une conspiration pour le nuisible. Car il est parfaitement sain, physiquement parlant, de se livrer avec une partenaire choisie à toutes les possibilités du joyeux mistère, selon la plaisante expression de nos pères ; tandis que l'on attrape des cirrhoses à boire de l'alcool.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "Oui, les vrais propagandistes d'un ordre nouveau, les vrais apôtres de la révolution future, future et dialectique, comme de bien entendu, sont les auteurs dits licencieux. Lire des livres érotiques, les faire connaître, les écrire, c'est préparer le monde de demain et frayer la voie de la vraie révolution.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "Le temps perdu c'est le temps pendant lequel on est à la merci des autres.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "Dans la vie, l'essentiel est de porter sur tout des jugements a priori. Il apparaît en effet que les masses ont tort, et les individus toujours raison. Il faut se garder d'en déduire des règles de conduite : elles ne doivent pas avoir besoin d'être formulées pour qu'on les suive. Il y a seulement deux choses : c'est l'amour, de toutes les façons, avec de jolies filles, et la musique de la Nouvelle-Orléans ou de Duke Ellington.", Author = "Boris Vian" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Vian", Text = "A quoi bon soulever des montagnes quand il est si simple de passer par-dessus ?", Author = "Boris Vian" },
